/**
 * One of the hint's buttons: it never takes the focus from the handle (a
 * press does not move it), and does what its key does.
 */
function HintButton({
  label,
  onPress,
  isText = false,
  children,
}: {
  label?: string;
  onPress: () => void;
  isText?: boolean;
