  scaleBy(factor: number): void {
    const scale = (sample: TouchSample): TouchSample => ({
      ...sample,
      x: sample.x * factor,
      y: sample.y * factor,
    });
    this.newest = this.newest == null ? null : scale(this.newest);
    this.moved = this.moved.map(scale);
    this.pan = {x: this.pan.x * factor, y: this.pan.y * factor};
