export function unwrapAngle(angle: number, reference: number): number {
  let result = angle;
  while (result - reference > Math.PI) {
    result -= 2 * Math.PI;
  }
  while (result - reference < -Math.PI) {
    result += 2 * Math.PI;
  }
  return result;
}

