        element,
        x: scrollsX && allowX,
        y: scrollsY && allowY,
        // The writing direction through core's one helper.
        isRtl: isRtlElement(element as HTMLElement),
        stopsX: behaviorX !== 'auto',
        stopsY: behaviorY !== 'auto',
