  if (!reachedRoot && isElement(root)) {
    chain.push({
      element: root,
      x: allowX && SCROLLABLE.has(rootOverflow(doc, 'x')),
      y: allowY && SCROLLABLE.has(rootOverflow(doc, 'y')),
